style.css:
/* Tema Nyan Cat para cualquier página */

@keyframes rainbowBG {
  0% {background-color:#ff0000;}
  16% {background-color:#ff7f00;}
  32% {background-color:#ffff00;}
  48% {background-color:#00ff00;}
  64% {background-color:#00ffff;}
  80% {background-color:#0000ff;}
  100% {background-color:#8b00ff;}
}

body {
  animation: rainbowBG 10s linear infinite !important;
  color: white !important;
  font-family: "Comic Sans MS", cursive !important;
}

/* Imagen de Nyan Cat flotando */
body::after {
  content: "";
  position: fixed;
  bottom: 20px;
  left: -200px;
  width: 200px;
  height: 120px;
  background-image: url("https://media.tenor.com/2roX3uxz_68AAAAC/nyan-cat.gif");
  background-size: contain;
  background-repeat: no-repeat;
  animation: nyanFly 15s linear infinite;
  pointer-events: none;
  z-index: 999999;
}

@keyframes nyanFly {
  0% {left:-200px;}
  100% {left:100%;}
}

/* Links estilo arcoíris */
a {
  color: #ff66ff !important;
  text-shadow: 0 0 5px #fff;
}
